data.script:
// ORB - Opening Range with Breakouts & Targets
// Based on "Opening Range with Breakouts & Targets" by LuxAlgo (mid-range % targets variant)
// License: CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/
// Ported to aggr by Aladhi.
// Boxes, lines and labels are drawn with brokenarea series. Previous bars points are edited during history replay
// (opening range rectangle, hidden previous sessions), live bars keep what was already drawn until the chart is reloaded.

showHist = option(type=checkbox, label="Show previous sessions", default=true)
orMinutes = option(type=number, label="Opening range length in minutes (from 00:00 UTC)", min=1, step=1, default=30)
customRange = option(type=checkbox, label="Use custom session instead", default=false)
customSession = option(type=text, label="Custom session (HHMM-HHMM)", default="0930-0945")
customTz = option(type=list, label="Custom session timezone", options=["UTC-10", "UTC-8", "UTC-7", "UTC-6", "UTC-5", "UTC-4", "UTC-3", "UTC+0", "UTC+1", "UTC+2", "UTC+3", "UTC+3:30", "UTC+4", "UTC+5", "UTC+5:30", "UTC+5:45", "UTC+6", "UTC+6:30", "UTC+7", "UTC+8", "UTC+9", "UTC+9:30", "UTC+10", "UTC+11", "UTC+12", "UTC+12:45", "UTC+13"], default="UTC-5")
showSignals = option(type=checkbox, label="Show breakout signals", default=true)
signalBias = option(type=list, label="Signal bias", options=["No Bias", "Daily Bias"], default="No Bias")
upSignalColor = option(type=color, label="Up signal", default="#089981")
downSignalColor = option(type=color, label="Down signal", default="#f23645")
showTargets = option(type=checkbox, label="Show targets", default=true)
firstTargetPct = option(type=number, label="First target % from mid-range", min=0.1, step=0.01, default=1.89)
nextTargetPct = option(type=number, label="Next targets spacing (% of range width)", min=1, step=1, default=50)
targetSource = option(type=list, label="Target cross source", options=["Close", "Highs/Lows"], default="Close")
targetDisplay = option(type=list, label="Target display", options=["Adaptive", "Extended"], default="Adaptive")
showMa = option(type=checkbox, label="Show session moving average", default=false)
maLength = option(type=number, label="Moving average length", min=1, max=500, step=1, default=20)
maType = option(type=list, label="Moving average type", options=["SMA", "EMA", "RMA", "WMA", "VWMA"], default="EMA")
maColor = option(type=color, label="Moving average", default="#FF9800")
bullTargetColor = option(type=color, label="Bull targets", default="#089981")
bearTargetColor = option(type=color, label="Bear targets", default="#f23645")
bullFillColor = option(type=color, label="Bull fill", default="rgba(8,153,129,0.2)")
bearFillColor = option(type=color, label="Bear fill", default="rgba(242,54,69,0.2)")
orLevelColor = option(type=color, label="Range levels", default="#787b86")
orHighlightColor = option(type=color, label="Range highlight", default="rgba(120,123,134,0.4)")

// series (filled programmatically)
brokenarea(color=orHighlightColor, strokeWidth=0)
brokenarea(color="transparent", strokeWidth=0)
brokenarea(color="transparent", strokeColor=orLevelColor, strokeWidth=1)
brokenarea(color="transparent", strokeColor=orLevelColor, strokeWidth=1)
brokenarea(color="transparent", strokeColor=orLevelColor, strokeWidth=1)
brokenarea(color="transparent", strokeColor=maColor, strokeWidth=1.5)
brokenarea(color="transparent", strokeColor=upSignalColor, strokeWidth=0, infinite=true)
brokenarea(color="transparent", strokeColor=downSignalColor, strokeWidth=0, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bullTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)
brokenarea(color="transparent", strokeColor=bearTargetColor, strokeWidth=1, infinite=true)

// "1:30" -> minutes, "0930-0945" + "UTC-5" -> { start, end, offset } in minutes
function parseSessionWindow(sessionText, tzText) {
  var sessionParts = String(sessionText).split('-')
  var startHm = parseInt(sessionParts[0], 10)
  var endHm = parseInt(sessionParts[1], 10)
  var tzBody = String(tzText).replace('UTC', '')
  var tzSign = tzBody.charAt(0) === '-' ? -1 : 1
  var tzParts = tzBody.slice(1).split(':')
  var tzMinutes = parseInt(tzParts[0], 10) * 60 + (tzParts.length > 1 ? parseInt(tzParts[1], 10) : 0)

  return {
    start: Math.floor(startHm / 100) * 60 + startHm % 100,
    end: Math.floor(endHm / 100) * 60 + endHm % 100,
    offset: tzSign * (tzMinutes || 0)
  }
}

function formatLevel(level) {
  var absLevel = Math.abs(level)
  var decimals = absLevel >= 1 ? 2 : Math.min(8, 3 - Math.floor(Math.log10(absLevel)))
  return level.toFixed(decimals)
}

// #rrggbb / rgb() / rgba() -> rgba() with the given alpha
function fadeColor(colorText, alpha) {
  var raw = String(colorText)
  if (raw.charAt(0) === '#' && raw.length >= 7) {
    return 'rgba(' + parseInt(raw.slice(1, 3), 16) + ',' + parseInt(raw.slice(3, 5), 16) + ',' + parseInt(raw.slice(5, 7), 16) + ',' + alpha + ')'
  }
  if (raw.indexOf('rgb') === 0) {
    var channels = raw.slice(raw.indexOf('(') + 1, raw.indexOf(')')).split(',')
    return 'rgba(' + channels[0] + ',' + channels[1] + ',' + channels[2] + ',' + alpha + ')'
  }
  return raw
}

// draw a point in the given series slot and remember it for this bar
function drawPoint(slot, point, kind) {
  renderer.series[series[slot].id] = point
  st.pending.push({ point: point, kind: kind })
}

// shared mutable state (not rolled back between ticks of a bar)
if (!st) {
  st = { bounds: {}, idx: -1, pending: [], session: [], box: [], targets: {} }

  for (var s = 0; s < series.length; s++) {
    if (series[s].seriesType && series[s].seriesType() === 'BrokenArea') {
      series[s].setExtensionsBoundaries(st.bounds)
    }
  }
}

var idx = bar.length - 1

// commit the points of the previous bar once a new bar starts (ticks of a same bar replace each other)
if (st.idx !== idx) {
  for (var c = 0; c < st.pending.length; c++) {
    st.session.push(st.pending[c].point)
    if (st.pending[c].kind === 'box') {
      st.box.push(st.pending[c].point)
    }
  }
  st.idx = idx
}
st.pending = []

var pHigh = $price.high
var pLow = $price.low
var pClose = $price.close
var isTimeChart = bar.type !== 'tick' && bar.type !== 'bps' && bar.type !== 'vol'
var enabled = !isTimeChart || bar.timeframe < 86400

// history
cls(501) = pClose
vlm(501) = vbuy + vsell

// opening range session
var dayMinute = Math.floor((((bar.timestamp % 86400) + 86400) % 86400) / 60)
var inSession = false
if (customRange) {
  var win = parseSessionWindow(customSession, customTz)
  var localMinute = (((dayMinute + win.offset) % 1440) + 1440) % 1440
  inSession = win.start < win.end ? localMinute >= win.start && localMinute < win.end : localMinute >= win.start || localMinute < win.end
} else {
  inSession = dayMinute < orMinutes
}

// work on last closed bar state so realtime ticks don't accumulate
// on the first bar, history [1] points to the current bar: use initial values instead
stamp = bar.timestamp
var first = stamp[1] === bar.timestamp
var cHi = first ? NaN : rangeHigh[1]
var cLo = first ? NaN : rangeLow[1]
var cPrevMid = first ? NaN : prevMid[1]
var cToken = first ? false : hasRange[1]
var cDir = first ? 0 : dayDir[1]
var cUpChk = first ? false : upCheck[1]
var cDnChk = first ? false : downCheck[1]
var cUpT = first ? NaN : upFirst[1]
var cDnT = first ? NaN : downFirst[1]
var cUpHi = first ? NaN : upExtreme[1]
var cDnLo = first ? NaN : downExtreme[1]
var cUpHit = first ? false : upFirstHit[1]
var cDnHit = first ? false : downFirstHit[1]
var cUpCnt = first ? 0 : upCount[1]
var cDnCnt = first ? 0 : downCount[1]
var cUpT1 = first ? false : upFirstDrawn[1]
var cDnT1 = first ? false : downFirstDrawn[1]
var cSid = first ? 0 : sessionId[1]
var cSince = first ? 0 : sinceStart[1] + 1
var prevClose = first ? NaN : cls[1]
var prevHigh = first ? NaN : rangeHigh[1]
var prevLow = first ? NaN : rangeLow[1]
var wasIn = first ? false : wasInSession[1]

var cMid = (cHi + cLo) / 2
var cWidth = Math.abs(cHi - cLo)
var hSrc = targetSource === "Close" ? pClose : pHigh
var lSrc = targetSource === "Close" ? pClose : pLow

var orStart = inSession && !wasIn
var orEnd = wasIn && !inSession

if (orStart) {
  cPrevMid = cSid > 0 ? cMid : NaN
  cHi = pHigh
  cLo = pLow
  cUpCnt = 0
  cDnCnt = 0
  cUpChk = true
  cDnChk = true
  cUpHit = false
  cDnHit = false
  cUpT1 = false
  cDnT1 = false
  cToken = false
  cSid = cSid + 1
  cSince = 0
}

if (inSession) {
  if (pHigh > cHi) {
    cHi = pHigh
  }
  if (pLow < cLo) {
    cLo = pLow
  }
  if (cHi !== cLo) {
    cToken = true
  }
}

if (orEnd && cToken) {
  cUpT = cMid + cMid * firstTargetPct / 100
  cDnT = cMid - cMid * firstTargetPct / 100
  cUpHi = cUpT + cWidth * nextTargetPct / 100
  cDnLo = cDnT - cWidth * nextTargetPct / 100
  cDir = cMid > cPrevMid ? 1 : cMid < cPrevMid ? -1 : 0
}

var post = !inSession && cToken
var step = cWidth * nextTargetPct / 100

// first target hits (only once the range is set, a hit during the range would point at the previous session targets)
if (post && hSrc > cUpT && !cUpHit) {
  cUpHit = true
  cUpHi = hSrc
}
if (post && lSrc < cDnT && !cDnHit) {
  cDnHit = true
  cDnLo = lSrc
}
if (cUpHit && hSrc > cUpHi) {
  cUpHi = hSrc
}
if (cDnHit && lSrc < cDnLo) {
  cDnLo = lSrc
}

var upMax = cUpHit && step > 0 ? Math.ceil((cUpHi - cUpT) / step) : 0
var dnMax = cDnHit && step > 0 ? Math.ceil((cDnT - cDnLo) / step) : 0
var upCur = cUpHit && step > 0 ? Math.max(0, Math.ceil((hSrc - cUpT) / step)) : 0
var dnCur = cDnHit && step > 0 ? Math.max(0, Math.ceil((cDnT - lSrc) / step)) : 0

// breakout signals
var upSignal = false
var downSignal = false
var prevWidth = Math.abs(prevHigh - prevLow)
var xDown = pClose < cLo && prevClose >= prevLow
var xDown2 = pClose < cLo - step && prevClose >= prevLow - prevWidth * nextTargetPct / 100
var xUp = pClose > cHi && prevClose <= prevHigh
var xUp2 = pClose > cHi + step && prevClose <= prevHigh + prevWidth * nextTargetPct / 100
var useBias = signalBias === "Daily Bias"

if (pClose > cMid && !cDnChk) {
  cDnChk = true
}
if ((useBias ? (cDir !== 1 && xDown) || (cDir === 1 && xDown2) : xDown) && cDnChk && cSid > 0) {
  downSignal = true
  cDnChk = false
}
if (pClose < cMid && !cUpChk) {
  cUpChk = true
}
if ((useBias ? (cDir !== -1 && xUp) || (cDir === -1 && xUp2) : xUp) && cUpChk && cSid > 0) {
  upSignal = true
  cUpChk = false
}

// session moving average (resets at range start)
var maLen = cSid > 0 ? Math.min(Math.max(cSince, 1), maLength) : maLength
var cMa = first ? 0 : maValue[1]
if (maType === "EMA") {
  cMa = pClose * (2 / (maLen + 1)) + cMa * (1 - 2 / (maLen + 1))
} else if (maType === "RMA") {
  cMa = pClose / maLen + cMa * (1 - 1 / maLen)
} else {
  var sumW = 0
  var sumV = 0
  for (var k = 0; k < maLen; k++) {
    if (typeof cls[k] === 'undefined') {
      break
    }
    var w = maType === "WMA" ? maLen - k : maType === "VWMA" ? vlm[k] : 1
    sumW += w
    sumV += cls[k] * w
  }
  cMa = sumW ? sumV / sumW : pClose
}

// drawings
if (enabled) {
  // previous session: labels go away, everything goes away when history is hidden
  if (orStart && st.session.length) {
    for (var o = 0; o < st.session.length; o++) {
      var old = st.session[o]
      delete old.label
      if (!showHist && !old.keep) {
        delete old.lowerValue
        delete old.higherValue
        delete old.extendRight
      }
    }
    st.session = []
    st.box = []
    st.targets = {}
  }

  // opening range box (earlier bars of the range are resized during history replay)
  if (inSession) {
    for (var b = 0; b < st.box.length; b++) {
      st.box[b].lowerValue = cLo
      st.box[b].higherValue = cHi
    }
    drawPoint(0, { time: time, lowerValue: cLo, higherValue: cHi }, 'box')
  }

  // range levels after the range
  if (post) {
    drawPoint(1, { time: time, lowerValue: cLo, higherValue: cHi, color: cDir === 1 ? bullFillColor : cDir === -1 ? bearFillColor : 'transparent' }, 'band')
    drawPoint(2, { time: time, lowerValue: cHi, higherValue: cHi, label: 'ORH ' + formatLevel(cHi) }, 'level')
    drawPoint(3, { time: time, lowerValue: cLo, higherValue: cLo, label: 'ORL ' + formatLevel(cLo) }, 'level')
    if (idx % 3 !== 2) {
      drawPoint(4, { time: time, lowerValue: cMid, higherValue: cMid }, 'level')
    }
  }

  // targets: one point per target extended to the right, stopped through boundaries
  // targets created on a same bar use alternating slots so two consecutive bars never share a slot
  if (showTargets && post && cUpT > 0) {
    var upSlot = 8 + (idx % 2) * 4
    var upUsed = 0
    while (upUsed < 4 && (!cUpT1 || (cUpHit && cUpCnt < upMax))) {
      var upIndex = 0
      if (!cUpT1) {
        cUpT1 = true
      } else {
        cUpCnt = cUpCnt + 1
        upIndex = cUpCnt
      }
      var upLevel = cUpT + step * upIndex
      var upId = 'u' + cSid + ':' + upIndex
      drawPoint(upSlot + upUsed, { time: time, lowerValue: upLevel, higherValue: upLevel, extendRight: true, id: upId, color: fadeColor(bullTargetColor, 0.4), label: 'T' + (upIndex + 1) + ' ' + formatLevel(upLevel) }, 'target')
      st.targets[upId] = { side: 1, index: upIndex }
      st.bounds[upId] = idx
      upUsed++
    }

    var downSlot = 16 + (idx % 2) * 4
    var downUsed = 0
    while (downUsed < 4 && (!cDnT1 || (cDnHit && cDnCnt < dnMax))) {
      var downIndex = 0
      if (!cDnT1) {
        cDnT1 = true
      } else {
        cDnCnt = cDnCnt + 1
        downIndex = cDnCnt
      }
      var downLevel = cDnT - step * downIndex
      var downId = 'd' + cSid + ':' + downIndex
      drawPoint(downSlot + downUsed, { time: time, lowerValue: downLevel, higherValue: downLevel, extendRight: true, id: downId, color: fadeColor(bearTargetColor, 0.4), label: 'T' + (downIndex + 1) + ' ' + formatLevel(downLevel) }, 'target')
      st.targets[downId] = { side: -1, index: downIndex }
      st.bounds[downId] = idx
      downUsed++
    }
  }

  if (showTargets) {
    for (var targetId in st.targets) {
      var tgt = st.targets[targetId]
      var cur = tgt.side > 0 ? upCur : dnCur
      if (targetDisplay === "Extended") {
        st.bounds[targetId] = idx
      } else if (tgt.index >= cur - 2 && tgt.index <= cur) {
        st.bounds[targetId] = idx + 1
      }
    }
  }

  if (showSignals && upSignal) {
    drawPoint(6, { time: time, lowerValue: cLo, higherValue: cLo, label: '▲' }, 'signal')
  }
  if (showSignals && downSignal) {
    drawPoint(7, { time: time, lowerValue: cHi, higherValue: cHi, label: '▼' }, 'signal')
  }

  if (showMa && !orStart) {
    drawPoint(5, { time: time, lowerValue: cMa, higherValue: cMa, keep: true }, 'ma')
  }
}

// save state
wasInSession = inSession
rangeHigh = cHi
rangeLow = cLo
prevMid = cPrevMid
hasRange = cToken
dayDir = cDir
upCheck = cUpChk
downCheck = cDnChk
upFirst = cUpT
downFirst = cDnT
upExtreme = cUpHi
downExtreme = cDnLo
upFirstHit = cUpHit
downFirstHit = cDnHit
upCount = cUpCnt
downCount = cDnCnt
upFirstDrawn = cUpT1
downFirstDrawn = cDnT1
sessionId = cSid
sinceStart = cSince
maValue = cMa
